file_editor: {"command": "create", "file_text": "package clusterdata.query;

import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;

import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.functions.MapFunction;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.common.typeinfo.TypeHint;
import org.apache.flink.api.common.typeinfo.TypeInformation;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.core.fs.FileSystem;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.co.KeyedCoProcessFunction;
import org.apache.flink.streaming.api.functions.source.SourceFunction;
import org.apache.flink.streaming.api.functions.windowing.ProcessWindowFunction;
import org.apache.flink.streaming.api.windowing.assigners.EventTimeSessionWindows;
import org.apache.flink.streaming.api.windowing.time.Time;
import org.apache.flink.streaming.api.windowing.windows.TimeWindow;
import org.apache.flink.util.Collector;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.time.Duration;
import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        final String taskInput = params.get("task_input", null);
        final String jobInput = params.get("job_input", null);
        final String outputPath = params.get("output", null);
        System.out.println("task_input  " + taskInput);
        System.out.println("job_input  " + jobInput);
        // session inactivity gap in seconds (default 10 minutes)
        final int sesssize = params.getInt("sesssize", 600);

        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(1);

        SourceFunction<TaskEvent> taskSrc = taskSourceOrTest(new GzipTaskEventSource(taskInput));
        SourceFunction<JobEvent> jobSrc = jobSourceOrTest(new GzipJobEventSource(jobInput));

        // Event-time strategy: task/job timestamps are in microseconds; convert to millis.
        WatermarkStrategy<TaskEvent> taskWm =
                WatermarkStrategy.<TaskEvent>forBoundedOutOfOrderness(Duration.ofSeconds(1))
                        .withTimestampAssigner((e, ts) -> e.timestamp / 1000L);
        WatermarkStrategy<JobEvent> jobWm =
                WatermarkStrategy.<JobEvent>forBoundedOutOfOrderness(Duration.ofSeconds(1))
                        .withTimestampAssigner((e, ts) -> e.timestamp / 1000L);

        DataStream<TaskEvent> tasks = env
                .addSource(taskSrc)
                .returns(TypeInformation.of(TaskEvent.class))
                .assignTimestampsAndWatermarks(taskWm);

        DataStream<JobEvent> jobs = env
                .addSource(jobSrc)
                .returns(TypeInformation.of(JobEvent.class))
                .assignTimestampsAndWatermarks(jobWm);

        // Session count per job. Event type 0 = SUBMIT.
        DataStream<Tuple2<Long, Long>> sessionCounts = tasks
                .filter(e -> e.eventType == 0)
                .keyBy(e -> e.jobId)
                .window(EventTimeSessionWindows.withGap(Time.seconds(sesssize)))
                .process(new CountSubmitsInSession())
                .returns(new TypeHint<Tuple2<Long, Long>>() {});

        // Job "finished" signal. Event type 4 = FINISH.
        DataStream<Tuple2<Long, Long>> finishes = jobs
                .filter(e -> e.eventType == 4)
                .map((MapFunction<JobEvent, Tuple2<Long, Long>>) e -> Tuple2.of(e.jobId, e.timestamp / 1000L))
                .returns(new TypeHint<Tuple2<Long, Long>>() {});

        DataStream<String> results = sessionCounts
                .keyBy(t -> t.f0)
                .connect(finishes.keyBy(t -> t.f0))
                .process(new EmitMaxOnFinish(sesssize * 1000L));

        if (outputPath != null) {
            // Remove any pre-existing file so writeAsText with parallelism 1 writes a fresh single file.
            try {
                Files.deleteIfExists(Paths.get(outputPath));
            } catch (Exception ignore) {
            }
            results.writeAsText(outputPath, FileSystem.WriteMode.OVERWRITE).setParallelism(1);
        } else {
            results.print();
        }

        env.execute("LongestSessionPerJob");
    }

    /**
     * Emits (jobId, count) for each session window on the SUBMIT task stream.
     */
    public static class CountSubmitsInSession
            extends ProcessWindowFunction<TaskEvent, Tuple2<Long, Long>, Long, TimeWindow> {
        @Override
        public void process(Long jobId, Context ctx, Iterable<TaskEvent> in, Collector<Tuple2<Long, Long>> out) {
            long n = 0;
            for (TaskEvent ignored : in) n++;
            out.collect(Tuple2.of(jobId, n));
        }
    }

    /**
     * Keeps the running max session count per job and emits (jobId,count) once the job's
     * FINISH event has been observed AND all sessions that could still land for that job
     * have surely closed (waits until the watermark passes finishTime + session gap).
     */
    public static class EmitMaxOnFinish
            extends KeyedCoProcessFunction<Long, Tuple2<Long, Long>, Tuple2<Long, Long>, String> {

        private final long gapMillis;
        private transient ValueState<Long> maxCountState;
        private transient ValueState<Long> finishTimerState;
        private transient ValueState<Boolean> emittedState;

        public EmitMaxOnFinish(long gapMillis) {
            this.gapMillis = gapMillis;
        }

        @Override
        public void open(Configuration parameters) {
            maxCountState = getRuntimeContext().getState(new ValueStateDescriptor<>("maxCount", Long.class));
            finishTimerState = getRuntimeContext().getState(new ValueStateDescriptor<>("finishTimer", Long.class));
            emittedState = getRuntimeContext().getState(new ValueStateDescriptor<>("emitted", Boolean.class));
        }

        @Override
        public void processElement1(Tuple2<Long, Long> in, Context ctx, Collector<String> out) throws Exception {
            Long cur = maxCountState.value();
            if (cur == null || in.f1 > cur) {
                maxCountState.update(in.f1);
            }
        }

        @Override
        public void processElement2(Tuple2<Long, Long> in, Context ctx, Collector<String> out) throws Exception {
            // in.f1 = job finish time in millis
            Long existing = finishTimerState.value();
            long fireAt = in.f1 + gapMillis + 1L;
            if (existing == null || fireAt > existing) {
                if (existing != null) {
                    ctx.timerService().deleteEventTimeTimer(existing);
                }
                ctx.timerService().registerEventTimeTimer(fireAt);
                finishTimerState.update(fireAt);
            }
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<String> out) throws Exception {
            Boolean emitted = emittedState.value();
            if (emitted != null && emitted) return;
            Long max = maxCountState.value();
            Long jobId = ctx.getCurrentKey();
            long value = (max == null) ? 0L : max;
            out.collect("(" + jobId + "," + value + ")");
            emittedState.update(true);
            maxCountState.clear();
            finishTimerState.clear();
        }
    }

    /**
     * Reads a gzipped task-events CSV file and emits TaskEvent records.
     * Google cluster-trace task_events columns:
     *   0 timestamp (us), 1 missing info, 2 jobId, 3 taskIndex, 4 machineId,
     *   5 eventType, 6 user, 7 schedClass, 8 priority, 9 cpu, 10 mem, 11 disk, 12 constraint
     */
    public static class GzipTaskEventSource implements SourceFunction<TaskEvent> {
        private final String path;
        private volatile boolean running = true;

        public GzipTaskEventSource(String path) {
            this.path = path;
        }

        @Override
        public void run(SourceContext<TaskEvent> ctx) throws Exception {
            try (BufferedReader br = new BufferedReader(new InputStreamReader(
                    new GZIPInputStream(Files.newInputStream(Paths.get(path))), StandardCharsets.UTF_8))) {
                String line;
                while (running && (line = br.readLine()) != null) {
                    String[] f = line.split(",", -1);
                    if (f.length < 6) continue;
                    try {
                        long ts = Long.parseLong(f[0].trim());
                        if (f[2].isEmpty() || f[5].isEmpty()) continue;
                        long jobId = Long.parseLong(f[2].trim());
                        int taskIndex = f[3].isEmpty() ? -1 : Integer.parseInt(f[3].trim());
                        int et = Integer.parseInt(f[5].trim());
                        ctx.collect(new TaskEvent(ts, jobId, taskIndex, et));
                    } catch (NumberFormatException ignore) {
                        // skip malformed row
                    }
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    /**
     * Reads a gzipped job-events CSV file and emits JobEvent records.
     * Google cluster-trace job_events columns:
     *   0 timestamp (us), 1 missing info, 2 jobId, 3 eventType,
     *   4 user, 5 schedClass, 6 jobName, 7 logicalJobName
     */
    public static class GzipJobEventSource implements SourceFunction<JobEvent> {
        private final String path;
        private volatile boolean running = true;

        public GzipJobEventSource(String path) {
            this.path = path;
        }

        @Override
        public void run(SourceContext<JobEvent> ctx) throws Exception {
            try (BufferedReader br = new BufferedReader(new InputStreamReader(
                    new GZIPInputStream(Files.newInputStream(Paths.get(path))), StandardCharsets.UTF_8))) {
                String line;
                while (running && (line = br.readLine()) != null) {
                    String[] f = line.split(",", -1);
                    if (f.length < 4) continue;
                    try {
                        long ts = Long.parseLong(f[0].trim());
                        if (f[2].isEmpty() || f[3].isEmpty()) continue;
                        long jobId = Long.parseLong(f[2].trim());
                        int et = Integer.parseInt(f[3].trim());
                        ctx.collect(new JobEvent(ts, jobId, et));
                    } catch (NumberFormatException ignore) {
                        // skip malformed row
                    }
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }
}
